const waterY = v.Y(3.2);
const botY = v.Y(0), leftX = v.X(0), rightX = v.X(10);
H.rect(leftX, waterY, rightX - leftX, botY - waterY, { fill: "#13314f" });
const ripple = 0.06 * Math.sin(t * 1.5);
H.line(leftX, waterY + ripple * 30, rightX, waterY + ripple * 30, { color: H.colors.accent, width: 2 });
const side = H.clamp(40 + 90 * Math.cbrt(V), 40, 130);
const cx = (leftX + rightX) / 2;
const bob = 4 * Math.sin(t * 1.5);
const topY = waterY - (1 - subFrac) * side + bob;
H.rect(cx - side / 2, topY, side, side, { fill: H.colors.accent2, stroke: H.colors.ink, width: 1.5, radius: 3 });
